import { ARMOR_BODY_ZONES, type ArmorBodyZone } from '../item-stage/armor-bundle.js';
import type { NpcWoundInstance } from './effect-types.js';

/** AQA-010/CORE-118, using the existing Items BODY_ZONE identities. The host proves the actual owner. */
export interface NpcWoundAnatomyContext {
  readonly anatomyProfileId: 'STANDARD_HUMANOID';
}
export type NpcGmWoundPreparation = Readonly<{
  /** Allocated and journal-bound by the host, never generated by this codec. */
  woundInstanceId: string;
  regionId: ArmorBodyZone;
}> &
  (Readonly<{ woundType: 'GENERIC' }> | Readonly<{ woundType: 'BLEEDING'; damagePerTick: number }>);

export class NpcWoundCodecError extends Error {
  constructor(path: string, detail: string) {
    super(`NPC wound ${path}: ${detail}`);
    this.name = new.target.name;
  }
}

// Effects/12 WoundInstance, including the GAP-001..003 required additions.
const FIELDS = [
  'woundInstanceId',
  'woundType',
  'regionId',
  'creationPolicy',
  'damagePerTick',
  'tickPhase',
  'healingPolicy',
] as const;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/u;

function fail(path: string, detail: string): never {
  throw new NpcWoundCodecError(path, detail);
}
function record(value: unknown, keys: readonly string[], path: string): Record<string, unknown> {
  if (value === null || typeof value !== 'object') return fail(path, 'expected plain data');
  const prototype: unknown = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    return fail(path, 'expected plain data');
  const own = Reflect.ownKeys(value);
  if (
    own.length !== keys.length ||
    own.some((key) => typeof key !== 'string' || !keys.includes(key))
  )
    return fail(path, 'unexpected or missing fields');
  const detached: Record<string, unknown> = {};
  for (const key of keys) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (descriptor === undefined || !descriptor.enumerable || !Object.hasOwn(descriptor, 'value'))
      return fail(path, 'expected enumerable own data fields');
    detached[key] = descriptor.value as unknown;
  }
  return detached;
}
function anatomy(context: unknown): void {
  const row = record(context, ['anatomyProfileId'], 'context');
  if (row['anatomyProfileId'] !== 'STANDARD_HUMANOID')
    fail('context.anatomyProfileId', 'AQA-010 requires STANDARD_HUMANOID for NPC');
}
function identity(value: unknown): string {
  if (typeof value !== 'string' || !UUID.test(value))
    return fail('woundInstanceId', 'expected canonical UUID v4');
  return value;
}
function region(value: unknown): ArmorBodyZone {
  return (
    ARMOR_BODY_ZONES.find((candidate) => candidate === value) ??
    fail('regionId', `unknown humanoid region; available: ${ARMOR_BODY_ZONES.join(', ')}`)
  );
}
function damage(value: unknown): number {
  // CORE-108: damage cannot heal; CORE-076 permits effective zero. Formula resolution is outside this codec.
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0)
    return fail('damagePerTick', 'expected explicit finite nonnegative effective damage');
  return value;
}

/** Closed saved shape only. Ownership, source event, GM authority and one-per-event replay belong to the host journal. */
export function readNpcWoundInstance(
  context: NpcWoundAnatomyContext,
  value: unknown,
): NpcWoundInstance {
  anatomy(context);
  const row = record(value, FIELDS, 'instance');
  const woundInstanceId = identity(row['woundInstanceId']),
    regionId = region(row['regionId']);
  if (
    row['creationPolicy'] !== 'SOURCE_CREATES_WOUND_OR_GM' ||
    row['healingPolicy'] !== 'EXPLICIT_TREATMENT_OR_GM_ONLY'
  )
    return fail('instance', 'source creation/healing policy differs');
  const common = {
    woundInstanceId,
    regionId,
    creationPolicy: 'SOURCE_CREATES_WOUND_OR_GM' as const,
    healingPolicy: 'EXPLICIT_TREATMENT_OR_GM_ONLY' as const,
  };
  if (row['woundType'] === 'GENERIC') {
    if (row['damagePerTick'] !== null || row['tickPhase'] !== null)
      return fail('instance', 'GENERIC has no bleeding damage or tick phase');
    return Object.freeze({ ...common, woundType: 'GENERIC', damagePerTick: null, tickPhase: null });
  }
  if (row['woundType'] !== 'BLEEDING') return fail('woundType', 'expected GENERIC or BLEEDING');
  if (row['tickPhase'] !== 'END_OF_TARGET_TURN')
    return fail('tickPhase', 'GAP-002 requires END_OF_TARGET_TURN');
  return Object.freeze({
    ...common,
    woundType: 'BLEEDING',
    damagePerTick: damage(row['damagePerTick']),
    tickPhase: 'END_OF_TARGET_TURN',
  });
}

/**
 * GAP-001/002: prepare one explicit GM assignment, not evidence of an attack or HP loss.
 * The owning authenticated host allocates the ID and records owner/originEventId separately.
 * No HP mutation, turn, clock, tick schedule, natural healing or provenance is synthesized here.
 */
export function prepareNpcGmWound(
  context: NpcWoundAnatomyContext,
  input: unknown,
): NpcWoundInstance {
  anatomy(context);
  if (input === null || typeof input !== 'object') return fail('input', 'expected plain data');
  const discriminator = Object.getOwnPropertyDescriptor(input, 'woundType');
  if (discriminator === undefined || !Object.hasOwn(discriminator, 'value'))
    return fail('input', 'missing own woundType');
  const woundType: unknown = discriminator.value;
  if (woundType !== 'GENERIC' && woundType !== 'BLEEDING')
    return fail('woundType', 'expected GENERIC or BLEEDING');
  const row = record(
    input,
    woundType === 'GENERIC'
      ? ['woundInstanceId', 'regionId', 'woundType']
      : ['woundInstanceId', 'regionId', 'woundType', 'damagePerTick'],
    'input',
  );
  return readNpcWoundInstance(context, {
    woundInstanceId: row['woundInstanceId'],
    regionId: row['regionId'],
    woundType,
    creationPolicy: 'SOURCE_CREATES_WOUND_OR_GM',
    healingPolicy: 'EXPLICIT_TREATMENT_OR_GM_ONLY',
    damagePerTick: woundType === 'BLEEDING' ? row['damagePerTick'] : null,
    tickPhase: woundType === 'BLEEDING' ? 'END_OF_TARGET_TURN' : null,
  });
}
